// @vitest-environment jsdom
import { describe, expect, it } from 'vitest';
import { AppUI } from '../ui';
import type { UISettings } from '../ui';
import { applyMatchOutcome, profileSummary, settingsToUi, uiToSettings } from './ProfileStore';
import type { MatchOutcome } from './ProfileStore';
import { SaveManager } from './SaveManager';
import type { StorageLike } from './SaveManager';

class MemoryStorage implements StorageLike {
  private readonly map = new Map<string, string>();
  getItem(key: string): string | null {
    return this.map.get(key) ?? null;
  }
  setItem(key: string, value: string): void {
    this.map.set(key, value);
  }
  removeItem(key: string): void {
    this.map.delete(key);
  }
}

const outcome = (overrides: Partial<MatchOutcome> = {}): MatchOutcome => ({
  rank: 1,
  playerCount: 4,
  holesPlayed: 9,
  holesCompleted: 9,
  totalStrokes: 31,
  coursePar: 27,
  holesInOne: 1,
  birdies: 2,
  durationSeconds: 600,
  xp: 190,
  ratingAfter: 1064,
  ...overrides,
});

describe('profile persistence', () => {
  it('keeps match progress across a reload', () => {
    const storage = new MemoryStorage();
    const fresh = new SaveManager(storage).load();
    expect(fresh.rating).toBe(1000);
    expect(fresh.progression.xp).toBe(0);
    expect(fresh.statistics.matchesPlayed).toBe(0);

    expect(new SaveManager(storage).save(applyMatchOutcome(fresh, outcome()))).toBe(true);

    const reloaded = new SaveManager(storage).load();
    expect(reloaded.progression.xp).toBe(190);
    expect(reloaded.rating).toBe(1064);
    expect(reloaded.statistics.matchesPlayed).toBe(1);
    expect(reloaded.statistics.matchesWon).toBe(1);
    expect(reloaded.statistics.totalStrokes).toBe(31);
    expect(reloaded.statistics.holesInOne).toBe(1);
    expect(reloaded.statistics.bestRoundStrokes).toBe(31);
  });

  it('accumulates across matches and unlocks cosmetics with the new level', () => {
    const storage = new MemoryStorage();
    const saves = new SaveManager(storage);
    saves.save(applyMatchOutcome(saves.load(), outcome({ xp: 3300, ratingAfter: 1042 })));
    saves.save(
      applyMatchOutcome(new SaveManager(storage).load(), outcome({ rank: 3, xp: 120, ratingAfter: 1017, totalStrokes: 40 })),
    );

    const reloaded = new SaveManager(storage).load();
    expect(reloaded.progression.xp).toBe(3420);
    expect(reloaded.progression.level).toBe(5);
    expect(reloaded.rating).toBe(1017);
    expect(reloaded.statistics.matchesPlayed).toBe(2);
    expect(reloaded.statistics.matchesWon).toBe(1);
    expect(reloaded.statistics.bestRoundStrokes).toBe(31);
    expect(reloaded.cosmetics.unlockedBallIds).toContain('marble-swirl');
  });

  it('stores the settings form and restores it after a reload', () => {
    const storage = new MemoryStorage();
    const saves = new SaveManager(storage);
    const profile = saves.load();
    const view: UISettings = { controlScheme: 'hold-to-charge', quality: 'ultra', volume: 45, reducedMotion: true };
    saves.save({ ...profile, settings: uiToSettings(view, profile.settings) });

    const reloaded = new SaveManager(storage).load();
    expect(reloaded.settings.controlScheme).toBe('charge');
    expect(reloaded.settings.qualityPreset).toBe('ultra');
    expect(reloaded.settings.masterVolume).toBeCloseTo(0.45, 5);
    expect(settingsToUi(reloaded.settings)).toEqual(view);
  });

  it('maps progression onto level-relative XP', () => {
    const storage = new MemoryStorage();
    const profile = applyMatchOutcome(new SaveManager(storage).load(), outcome({ xp: 600, ratingAfter: 1100 }));
    const summary = profileSummary(profile);
    expect(summary.level).toBe(2);
    expect(summary.xp).toBe(100);
    expect(summary.xpNext).toBe(700);
    expect(summary.rating).toBe(1100);
    expect(summary.matches).toBe(1);
  });
});

describe('menu screens read the stored profile', () => {
  it('shows the saved rating, level and statistics', () => {
    const storage = new MemoryStorage();
    const saves = new SaveManager(storage);
    saves.save(applyMatchOutcome(saves.load(), outcome({ xp: 3300, ratingAfter: 1064 })));
    const reloaded = new SaveManager(storage).load();

    const root = document.createElement('div');
    new AppUI(root, {}, { profile: profileSummary(reloaded), settings: settingsToUi(reloaded.settings) });
    expect(root.textContent).toContain('Rating 1064');

    root.querySelector<HTMLElement>('[data-nav="profile"]')?.click();
    const text = root.textContent ?? '';
    expect(text).toContain('Level 5');
    expect(text).toContain('Rating 1064');
    expect(text).toContain('100 / 1300 XP');
    expect(text).toContain('31');
  });

  it('preselects the stored settings and reports edits back', () => {
    const root = document.createElement('div');
    const saved: UISettings[] = [];
    new AppUI(
      root,
      { saveSettings: (next) => saved.push(next) },
      { settings: { controlScheme: 'hold-to-charge', quality: 'ultra', volume: 45, reducedMotion: true } },
    );
    root.querySelector<HTMLElement>('[data-nav="settings"]')?.click();

    expect(root.querySelector<HTMLSelectElement>('select[name="controls"]')?.value).toBe('hold-to-charge');
    expect(root.querySelector<HTMLSelectElement>('select[name="quality"]')?.value).toBe('ultra');
    expect(root.querySelector<HTMLInputElement>('input[name="motion"]')?.checked).toBe(true);
    expect(root.querySelector<HTMLInputElement>('input[name="volume"]')?.value).toBe('45');

    const quality = root.querySelector<HTMLSelectElement>('select[name="quality"]');
    if (quality) quality.value = 'low';
    root.querySelector<HTMLFormElement>('[data-settings]')?.dispatchEvent(new Event('submit', { cancelable: true }));
    expect(saved).toHaveLength(1);
    expect(saved[0]?.quality).toBe('low');
    expect(saved[0]?.controlScheme).toBe('hold-to-charge');
    expect(saved[0]?.reducedMotion).toBe(true);

    const storage = new MemoryStorage();
    const saves = new SaveManager(storage);
    const profile = saves.load();
    saves.save({ ...profile, settings: uiToSettings(saved[0]!, profile.settings) });
    expect(new SaveManager(storage).load().settings.qualityPreset).toBe('low');
  });
});
